pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address x, address y) public {
        vm.assume(x != address(0) && x != address(this));
        vm.assume(y != address(0));
        // step 1: current owner (this contract) transfers ownership to x
        assertTrue(c.setOwner(x));
        // step 2: the new owner x transfers ownership to y; must succeed and take effect
        vm.prank(x);
        bool ok;
        try c.setOwner(y) { ok = true; } catch { ok = false; }
        assertTrue(ok && c.owner() == y);
    }
}

