pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        // The deployer (this test contract) is the initial owner; only it can succeed.
        bool ok;
        vm.prank(actor);
        try c.setOwner(newOwner) returns (bool s) {
            ok = s;
        } catch {
            ok = false;
        }
        // General rule: whenever setOwner reports success, the resulting owner
        // is exactly the requested newOwner — ownership moves only where requested.
        assertTrue(!ok || c.owner() == newOwner, "successful setOwner must set owner to the requested newOwner");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // wide domain: any address except the current owner (this test contract)
        vm.assume(newOwner != address(this));

        // current owner (setUp's deployer) transfers ownership to the fuzzed address
        bool okFirst;
        try c.setOwner(newOwner) { okFirst = true; } catch { okFirst = false; }

        // the previous owner attempts another setOwner afterwards
        bool okSecond;
        try c.setOwner(address(this)) { okSecond = true; } catch { okSecond = false; }

        // Rule: once ownership was transferred to newOwner != previous owner,
        // the previous owner must no longer be able to call setOwner.
        assertTrue(!(okFirst && okSecond));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, address newOwner) public {
        // admissible domain: any caller, any requested new owner (kept wide)
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool s) { ok = s; } catch { ok = false; }

        // Universal rule: whenever the caller is the current owner, the call must
        // succeed and owner must end up exactly equal to the requested newOwner;
        // whenever the caller is not the owner, the call must revert and ownership
        // must be unchanged. This is the complete externally observable contract of
        // setOwner for every (caller, newOwner) pair.
        if (caller == address(this)) {
            assertTrue(ok && c.owner() == newOwner);
        } else {
            assertTrue(!ok && c.owner() == address(this));
        }
    }
}

