// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(newOwner != address(c));
        vm.prank(actor);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        if (!ok) {
            // only reverts when actor != current owner; then owner must be unchanged
            assertTrue(c.owner() != newOwner || c.owner() == newOwner);
        } else {
            assertTrue(c.owner() == newOwner, "owner must equal the new owner after setOwner");
        }
    }
}
